        .info-item {
            margin-bottom: 12px;
            font-size: 14px;
            line-height: 1.5;
        }

        .info-item:last-child {
            margin-bottom: 0;
        }

        .info-label {
            font-weight: bold;
            color: #ff6b81;
            display: block;
            margin-bottom: 2px;
        }

        .rsvp-section {
            text-align: center;
        }

        .rsvp-title {
            font-size: 16px;
            font-weight: bold;
            margin-bottom: 12px;
            color: #2f3542;
